macro_rules! recurse {
    () => {
        # [doc = " Sorts `v` recursively."] # [doc = ""] # [doc = " If the slice had a predecessor in the original array, it is specified as `pred`."] # [doc = ""] # [doc = " `limit` is the number of allowed imbalanced partitions before switching to `heapsort`. If zero,"] # [doc = " this function will immediately switch to heapsort."] fn recurse < 'a , T , F > (mut v : & 'a mut [T] , is_less : & F , mut pred : Option < & 'a mut T > , mut limit : u32) where T : Send , F : Fn (& T , & T) -> bool + Sync , { const MAX_INSERTION : usize = 20 ; const MAX_SEQUENTIAL : usize = 2000 ; let mut was_balanced = true ; let mut was_partitioned = true ; loop { let len = v . len () ; if len <= MAX_INSERTION { if len >= 2 { insertion_sort_shift_left (v , 1 , is_less) ; } return ; } if limit == 0 { heapsort (v , is_less) ; return ; } if ! was_balanced { break_patterns (v) ; limit -= 1 ; } let (pivot , likely_sorted) = choose_pivot (v , is_less) ; if was_balanced && was_partitioned && likely_sorted { if partial_insertion_sort (v , is_less) { return ; } } if let Some (& mut ref p) = pred { if ! is_less (p , & v [pivot]) { let mid = partition_equal (v , pivot , is_less) ; v = & mut v [mid ..] ; continue ; } } let (mid , was_p) = partition (v , pivot , is_less) ; was_balanced = cmp :: min (mid , len - mid) >= len / 8 ; was_partitioned = was_p ; let (left , right) = v . split_at_mut (mid) ; let (pivot , right) = right . split_at_mut (1) ; let pivot = & mut pivot [0] ; if Ord :: max (left . len () , right . len ()) <= MAX_SEQUENTIAL { if left . len () < right . len () { recurse (left , is_less , pred , limit) ; v = right ; pred = Some (pivot) ; } else { recurse (right , is_less , Some (pivot) , limit) ; v = left ; } } else { rayon_core :: join (| | recurse (left , is_less , pred , limit) , | | recurse (right , is_less , Some (pivot) , limit) ,) ; break ; } } }
    };
}

recurse!();